#include <cstddef>
#include <cstdint>
namespace{constexpr std::size_t N=16,K=4,L=66;void put64(std::uint8_t*o,std::size_t p,std::int64_t x){auto b=static_cast<std::uint64_t>(x);for(std::size_t j=0;j<8;j++){o[p+j]=static_cast<std::uint8_t>(b&255U);b>>=8;}}}
extern "C" std::int64_t min_hash_k_mins(const std::int64_t*in,std::size_t len,std::uint8_t*out,std::size_t cap)noexcept{if(!in||len<3||len>L)return -1;auto nr=in[0],kr=in[1];if(nr<1||nr>N||kr<1||kr>K||len!=2+static_cast<std::size_t>(nr*kr))return -1;auto n=static_cast<std::size_t>(nr),k=static_cast<std::size_t>(kr);for(std::size_t i=0;i<n*k;i++)if(in[2+i]<0||in[2+i]>1000)return -1;auto bytes=8*k;if(!out||cap<bytes)return -2;for(std::size_t col=0;col<k;col++){std::size_t best=0;for(std::size_t row=1;row<n;row++)if(in[2+row*k+col]<in[2+best*k+col])best=row;auto b=static_cast<std::uint64_t>(best);for(std::size_t j=0;j<8;j++){out[8*col+j]=static_cast<std::uint8_t>(b&255U);b>>=8;}}return static_cast<std::int64_t>(bytes);}
